from PIL import Image
import numpy as np
from scipy import ndimage as ndi
im=np.array(Image.open('/app/target.png').convert('RGB'))
mask=(im.mean(2)<100)
print('mask',mask.sum(),'bbox',np.where(mask)[1].min(),np.where(mask)[1].max(),np.where(mask)[0].min(),np.where(mask)[0].max())
sk=mask.copy()
# Zhang-Suen
n=0
while True:
 changed=False
 for phase in (0,1):
  p=np.pad(sk,1)
  P=[p[0:-2,1:-1],p[0:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
  N=sum(x.astype(np.uint8) for x in P)
  # circular transitions false->true
  T=sum((~P[i])&P[(i+1)%8] for i in range(8))
  c=(sk&(N>=2)&(N<=6)&(T==1))
  if phase==0: c &= ~(P[0]&P[2]&P[4]) & ~(P[2]&P[4]&P[6])
  else: c &= ~(P[0]&P[2]&P[6]) & ~(P[0]&P[4]&P[6])
  if c.any(): sk[c]=False; changed=True
 if not changed: break
 n+=1
print('iterations',n,'skeleton',sk.sum())
p=np.pad(sk.astype(np.uint8),1)
deg=np.zeros_like(sk,dtype=np.uint8)
for dy in (-1,0,1):
 for dx in (-1,0,1):
  if dx or dy: deg+=p[1+dy:1+dy+sk.shape[0],1+dx:1+dx+sk.shape[1]]
yx=np.argwhere(sk)
ends=np.argwhere(sk&(deg==1)); br=np.argwhere(sk&(deg>=3))
print('ends',len(ends),ends[:100].tolist(),'branches',len(br),br[:20].tolist())
# branch connected clusters via 8-neighbor
lbl,num=ndi.label(deg>=3,structure=np.ones((3,3)))
for k in range(1,num+1):
 yy,xx=np.where(lbl==k); print('branchcluster',k,len(xx),(xx.min(),xx.max(),yy.min(),yy.max()),(xx.mean(),yy.mean()))
# dijkstra graph
import heapq, math
coords=set(map(tuple,yx.tolist()))
def neigh(pt):
 y,x=pt
 for dy in (-1,0,1):
  for dx in (-1,0,1):
   if dx or dy:
    q=(y+dy,x+dx)
    if q in coords: yield q,math.sqrt(dx*dx+dy*dy)
def shortest(a,b):
 pq=[(0,a)]; dist={a:0}; prev={}
 while pq:
  d,u=heapq.heappop(pq)
  if u==b: break
  if d!=dist[u]:continue
  for v,w in neigh(u):
   nd=d+w
   if nd<dist.get(v,1e9):dist[v]=nd;prev[v]=u;heapq.heappush(pq,(nd,v))
 path=[b]
 while path[-1]!=a:path.append(prev[path[-1]])
 return path[::-1],dist[b]
print('end degrees',[(tuple(a),int(deg[tuple(a)])) for a in ends])
# width EDT at skeleton
edt=ndi.distance_transform_edt(mask)
for e in ends:
 print('endpoint',tuple(e),'distance px',float(edt[tuple(e)]))
# emit each endpoint pair shortest with simplified every 20px path distance
for i,a in enumerate(ends):
 for b in ends[i+1:]:
  path,L=shortest(tuple(a),tuple(b))
  if L>150:
   vals=[]; prev=path[0]; acc=0
   for j,pt in enumerate(path):
    if j: acc+=math.dist(prev,pt); prev=pt
    if acc>=20 or j==len(path)-1:
     y,x=pt; vals.append((round(x),round(y),round(float(edt[y,x]*2),1))); acc=0
   print('PAIR',tuple(a),tuple(b),'length px',L,'samples',vals)
